import {
    Table,
    TranslatedTextColumn,
    BooleanColumn,
    GenericColumn,
    StringColumn,
    ReferenceColumn,
    ListColumn,
    TranslatedFieldColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const sc_catalog = Table({
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    display: 'title',
    extends: 'sys_metadata',
    label: 'Catalog',
    name: 'sc_catalog',
    schema: {
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Description',
            maxLength: 4000,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        desktop_image: GenericColumn({
            attributes: {
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: [
                {
                    hint: 'The picture to use when displayed on the Catalogs page',
                    label: 'Desktop image',
                    plural: 'Desktop images',
                    language: 'en',
                },
            ],
        }),
        desktop_continue_shopping: StringColumn({
            label: [
                {
                    hint: "The page name for the redirect when the user clicks 'Continue Shopping'",
                    label: "'Continue Shopping' page",
                    plural: "'Continue Shopping' pages",
                    language: 'en',
                },
            ],
            maxLength: 3000,
        }),
        desktop_home_page: StringColumn({
            label: [
                {
                    hint: 'A custom page to redirect to when a user clicks the catalog within a breadcrumb',
                    label: "'Catalog Home' Page",
                    plural: "'Catalog Home' Pages",
                    language: 'en',
                },
            ],
            maxLength: 3000,
        }),
        manager: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Catalog Manager is able to Edit/Update/Delete Catalogs, Categories and Items',
                    label: 'Manager',
                    plural: 'Managers',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_user',
            referenceQual: "javascript:'sys_idIN'+getManagerUsers()",
        }),
        editors: ListColumn({
            attributes: {
                no_add_me: true,
                no_email: true,
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Catalog Editor is able to Edit/Update Catalogs, Categories and Items',
                    label: 'Editors',
                    plural: 'Editors',
                    language: 'en',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_user',
            referenceQual: "javascript:'sys_idIN'+getEditorUsers()",
        }),
        enable_wish_list: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Enables wish list functionality for items in the catalog. Partially filled items can be saved to cart. Only available in doctype mode.',
                    label: 'Enable Wish List',
                    plural: 'Enable Wish Lists',
                    language: 'en',
                },
            ],
        }),
        title: TranslatedFieldColumn({
            label: [
                {
                    hint: 'The title of the catalog. This must be unique.',
                    label: 'Title',
                    plural: 'Titles',
                    language: 'en',
                },
            ],
            mandatory: true,
            maxLength: 100,
            textIndex: true,
            unique: true,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
})
